create or replace function public.chat_content_violation(p_body text) returns text language plpgsql immutable set search_path=public as $$ declare clean text; compact text; words text; word text; begin clean := lower(normalize(coalesce(p_body,''),NFKC)); clean := translate(clean,'013457@$!','oieastasi'); clean := translate(clean,'аеіорсху','aeiopcxy'); clean := regexp_replace(clean,'[​‌‍﻿]','','g'); compact := regexp_replace(clean,'[^a-z]','','g'); words := regexp_replace(clean,'[^a-z]+',' ','g'); foreach word in array array['fuck','fucking','fucker','motherfucker','bitch','bastard','cunt','nigger','nigga','faggot','retard'] loop if words ~ ('\m'||word||'\M') or clean ~ ('\m'||array_to_string(regexp_split_to_array(word,''),'[[:space:][:punct:]]*')||'\M') then return 'Harassment or abusive language is not allowed.'; end if; end loop; if compact ~ '(fuckyou|fuckyour|motherfucker|killyourself|killurself|iwillkillyou|imgoingtokillyou|youareworthless|youreworthless|godie)' or words ~ '\mkys\M' then return 'Harassment or abusive language is not allowed.'; end if; if clean ~ '(.)\1{11,}' or clean ~ '(\m[a-z]{2,}\M)([[:space:][:punct:]]+\1){5,}' or (select count(*) from regexp_matches(clean,'https?://|www\.','g'))>3 then return 'Repeated text or too many links: please avoid spam.'; end if; return null; end $$;